mapper.select:
SELECT id, tenant_id, task_id, project_id, platform_request_id, integration_status_code, external_system_code, external_request_id, external_application_no, launch_url, current_status_revision_id, retry_count, last_failure_code, last_failure_detail, last_attempt_time, version, creator, create_time, updater, update_time, deleted, need_required_flag, task_no, source_task_version, correlation_id FROM cut_spare_application_reference
WHERE tenant_id = #{query.tenantId}
  AND external_system_code = #{query.externalSystemCode}
  AND external_application_no = #{query.externalApplicationNo}
  AND deleted = b'0'
FOR UPDATE

mapper.update:
UPDATE cut_spare_application_reference
SET external_application_no = #{query.externalApplicationNo}, integration_status_code = 'EXTERNAL_REFERENCED',
    version = #{query.expectedVersion} + 1, updater = #{query.updater}, update_time = #{query.updateTime}
WHERE tenant_id = #{query.tenantId} AND id = #{query.applicationReferenceId}
  AND external_request_id = #{query.externalRequestId} AND external_application_no IS NULL
  AND integration_status_code = 'REQUEST_PENDING' AND version = #{query.expectedVersion} AND deleted = b'0'

UPDATE cut_spare_application_reference
SET current_status_revision_id = #{query.currentStatusRevisionId}, version = #{query.expectedVersion} + 1,
    updater = #{query.updater}, update_time = #{query.updateTime}
WHERE tenant_id = #{query.tenantId} AND id = #{query.applicationReferenceId}
  AND version = #{query.expectedVersion} AND deleted = b'0'
